SELECT MAX(RACES.YEAR) AS LAST_SEASON FROM CIRCUITS INNER JOIN RACES ON CIRCUITS.CIRCUITID = RACES.CIRCUITID WHERE CIRCUITS.NAME = 'BRANDS HATCH' AND RACES.NAME = 'BRITISH GRAND PRIX';
-- ----------sql2------------
