-- ----------sql1------------
-- 2147483649
SELECT L.NAME AS LEAGUE_NAME FROM MATCH AS M INNER JOIN LEAGUE AS L ON M.LEAGUE_ID = L.ID WHERE M.SEASON = '2015/2016' GROUP BY L.ID, L.NAME ORDER BY SUM(CASE WHEN M.HOME_TEAM_GOAL = M.AWAY_TEAM_GOAL THEN 1 ELSE 0 END) DESC LIMIT 1;
-- ----------sql2------------
-- 2147483650
SELECT T2.NAME FROM MATCH AS T1 INNER JOIN LEAGUE AS T2 ON T1.LEAGUE_ID = T2.ID WHERE T1.SEASON = '2015/2016' AND T1.HOME_TEAM_GOAL = T1.AWAY_TEAM_GOAL GROUP BY T2.NAME ORDER BY COUNT(T1.ID) DESC LIMIT 1;

