SELECT DRIVERS.FORENAME, DRIVERS.SURNAME FROM RESULTS INNER JOIN DRIVERS ON RESULTS.DRIVERID = DRIVERS.DRIVERID WHERE RESULTS.RACEID = 592 AND RESULTS.TIME IS NOT NULL ORDER BY DRIVERS.DOB ASC LIMIT 1;
